def counted_scan(n):
    visits = 0
    for _ in range(n):
        visits += 1
    return visits

def counted_pairs(n):
    pairs = 0
    for i in range(n):
        for _ in range(i + 1, n):
            pairs += 1
    return pairs

def counted_halvings(n):
    steps = 0
    while n > 1:
        n //= 2
        steps += 1
    return steps

for n in [8, 16]:
    print(n, counted_scan(n), counted_pairs(n), counted_halvings(n))
